def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0.0)))
                except Exception:
                    pass

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 3 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarce = supply <= 17
    ample = supply >= 22
    critical = hp <= 3 or no_water >= 1
    desperate = hp <= 2 or no_water >= 2

    if desperate:
        bid = max(DAILY_SALARY * 1.15, highest_prev + 3.0)
    elif critical:
        if scarce:
            bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.8, avg_prev + 1.5)
    else:
        if ample:
            bid = DAILY_SALARY * 0.28
        elif scarce:
            if highest_prev >= 130:
                bid = DAILY_SALARY * 0.42
            else:
                bid = max(DAILY_SALARY * 0.55, highest_prev + 1.0)
        else:
            if highest_prev >= 140:
                bid = DAILY_SALARY * 0.38
            else:
                bid = max(DAILY_SALARY * 0.48, min(highest_prev + 1.0, DAILY_SALARY * 0.9))

    if day >= 8 and hp >= 6 and no_water == 0 and not scarce:
        bid = min(bid, DAILY_SALARY * 0.4)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = max(0.0, budget - DAILY_SALARY * (10 - day) * 0.55)
        bid = max(min(bid, budget), min(budget, reserve_floor))

    bid = min(budget, max(0.0, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
