def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.5)

    yesterday_bids = []
    desperate_opponents = 0
    competitive_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev_trace = opp.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                yesterday_bids.append(prev_trace['bid'])

                if opp['hp'] <= 2 and prev_trace.get('status') != 'got_water':
                    desperate_opponents += 1
                elif opp['hp'] >= 5 and prev_trace.get('status') == 'got_water':
                    competitive_opponents += 1

    base_bid = DAILY_SALARY * 0.65

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 1.05
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.85
    elif my_hp <= 6:
        base_bid = DAILY_SALARY * 0.75

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid + 5)
        else:
            base_bid = max(base_bid, highest_prev_bid + 10)

    if desperate_opponents > 0:
        base_bid += DAILY_SALARY * 0.1 * desperate_opponents

    if competitive_opponents > 0:
        base_bid = max(base_bid, DAILY_SALARY * 0.7)

    days_left = EPISODE_DAYS - current_day
    if days_left <= 2:
        base_bid *= 1.1

    final_bid = min(my_budget, base_bid)

    return max(1.0, final_bid)
